dth:700px){.platform-page{padding:20px 14px 50px}.platform-hero{padding:20px;align-items:flex-start}.hero-stat{min-width:70px;padding-left:12px}.hero-stat strong{font-size:32px}.action-card{grid-template-columns:1fr;gap:10px;padding:16px}.date{flex-direction:row}.impact{grid-template-columns:1fr}.foot{flex-direction:column}}
